const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// Configuración base\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// 1. Cliente (Tenant)\nmodel Tenant {\n  id        String   @id @default(uuid())\n  name      String\n  sector    String?\n  status    String   @default(\"ACTIVE\") // ACTIVE | SUSPENDED | DELETING\n  createdAt DateTime @default(now())\n\n  // Eliminación manual en curso (estado DELETING): momento en que se solicitó.\n  // Permite reintentar la eliminación tras reinicios (estado persistente).\n  deletionRequestedAt DateTime?\n\n  // Política de retención (la define el admin del cliente)\n  retentionMode String @default(\"FULL\") // FULL = video + métricas | METRICS = solo métricas\n  retentionDays Int    @default(90)\n\n  // Cambio de plan PROGRAMADO (persistente): se aplica cuando llega `retentionEffectiveAt`.\n  // Permite que un cambio de plan no altere retroactivamente las sesiones que ya están bajo el\n  // plan vigente (ver lib/retentionPlan.js). null = no hay cambio pendiente.\n  retentionModePending String?\n  retentionDaysPending Int?\n  retentionEffectiveAt DateTime?\n\n  // Estilo de la plataforma (lo define el admin del cliente). null = colores de VoxReady\n  brandColor  String? // Color principal, formato #RRGGBB\n  accentColor String? // Color de acento, formato #RRGGBB\n\n  // Idioma por defecto de la organización: lo usa el vocero mientras no fije su propia\n  // preferencia (User.language). Valores soportados: 'es' | 'en'.\n  defaultLanguage String @default(\"es\")\n\n  users    User[]\n  themes   Theme[]\n  sessions Session[]\n\n  deletionRequests DeletionRequest[]\n\n  // Solicitudes de extensión del plazo de conservación (operación distinta a las de privacidad)\n  retentionExtensionRequests RetentionExtensionRequest[]\n}\n\n// 2. Usuario (Vocero, Admin, Maestro)\nmodel User {\n  id    String @id @default(uuid())\n  email String @unique\n  name  String\n  role  String @default(\"VOCERO\") // VOCERO | ADMIN | MASTER | SYSTEM\n\n  // Acceso\n  passwordHash String?\n  status       String    @default(\"ACTIVE\") // ACTIVE | SUSPENDED\n  area         String? // Público interno del vocero (Dirección, Planta, Técnicos)\n  createdAt    DateTime  @default(now())\n  lastLoginAt  DateTime?\n\n  // Anonimización (Bloque A): si tiene fecha, el vocero fue anonimizado\n  // (name/email/area sin PII, sin password) pero el registro y su histórico se conservan\n  anonymizedAt DateTime?\n\n  // Preferencia individual de idioma ('es' | 'en'). null = hereda el idioma por defecto de su\n  // organización. Cambiar el idioma del tenant no altera a quien ya eligió el suyo.\n  language String?\n\n  // El staff de VoxReady (MASTER y SYSTEM) no pertenece a una organización\n  tenantId String?\n  tenant   Tenant? @relation(fields: [tenantId], references: [id])\n\n  sessions       Session[]\n  assignments    ScenarioAssignment[]\n  masterPatterns MasterPattern[]\n\n  // Patrón de evaluación excepcional para este vocero (lo asigna el configurador maestro)\n  patternOverride VoceroPatternOverride?\n\n  // Solicitudes de borrado (creadas / dirigidas a / resueltas por)\n  deletionRequestsMade     DeletionRequest[] @relation(\"DeletionRequestedBy\")\n  deletionRequestsTargeted DeletionRequest[] @relation(\"DeletionRequestTarget\")\n  deletionRequestsResolved DeletionRequest[] @relation(\"DeletionRequestResolvedBy\")\n\n  // Solicitudes de extensión del plazo de retención (creadas / resueltas por)\n  retentionExtensionsMade     RetentionExtensionRequest[] @relation(\"RetentionExtensionRequestedBy\")\n  retentionExtensionsResolved RetentionExtensionRequest[] @relation(\"RetentionExtensionResolvedBy\")\n\n  // Intervalos en que la retención de este usuario estuvo PAUSADA\n  // (por suspensión propia y/o de su tenant; se registra la unión, sin solapamientos)\n  retentionPauses RetentionPause[]\n}\n\n// 3. Tema / Escenario\nmodel Theme {\n  id          String @id @default(uuid())\n  title       String\n  context     String @db.Text\n  keyMessages String @db.Text\n  category    String @default(\"GENERAL\")\n\n  optic    String?\n  publics  String?\n  redLines String?\n\n  availableToAllVoceros Boolean @default(false)\n\n  // Borrado lógico: un tema \"eliminado\" deja de estar disponible pero conserva\n  // su histórico (asignaciones, sesiones, informes y videos)\n  deletedAt DateTime?\n\n  // Escenario general de la biblioteca de VoxReady: no pertenece a ninguna\n  // organización (tenantId vacío) y lo ven todos los voceros\n  isGlobal Boolean @default(false)\n\n  // Idioma del escenario ('es' | 'en'). En los escenarios generales distingue el catálogo\n  // (español o inglés); en los escenarios de una organización indica en qué idioma está escrito\n  // su contenido. Nunca se traduce automáticamente.\n  language String @default(\"es\")\n\n  // Configuración de la entrevista (ver ai/interviewConfig.js): nivel de agresividad,\n  // cantidad de preguntas y repreguntas, tiempo estimado, quién entrevista y tiempo por respuesta.\n  // null = valores por defecto\n  interviewConfig Json?\n\n  tenantId String?\n  tenant   Tenant? @relation(fields: [tenantId], references: [id], onDelete: Restrict)\n\n  sessions    Session[]\n  assignments ScenarioAssignment[]\n\n  // Patrón de evaluación excepcional para este escenario (lo asigna el configurador maestro)\n  patternOverride PatternOverride?\n\n  @@unique([tenantId, title])\n}\n\n// 4. Asignación de un escenario a un vocero\nmodel ScenarioAssignment {\n  id String @id @default(uuid())\n\n  status      String          @default(\"PENDING\")\n  assignedAt  DateTime        @default(now())\n  completedAt DateTime?\n  rubric      ScenarioRubric?\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  themeId String\n  theme   Theme  @relation(fields: [themeId], references: [id])\n\n  @@unique([userId, themeId])\n}\n\n// 5. Sesión de práctica\nmodel Session {\n  id        String   @id @default(uuid())\n  status    String   @default(\"CREATED\")\n  createdAt DateTime @default(now())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  themeId String\n  theme   Theme  @relation(fields: [themeId], references: [id])\n\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id])\n\n  // Resultado de la práctica\n  completedAt  DateTime?\n  transcript   Json? // Preguntas y respuestas de la entrevista\n  metrics      Json? // Métricas de voz, cuerpo e iluminación medidas en el navegador\n  report       Json? // Informe generado por la IA evaluadora\n  score        Int? // Puntaje global 0-100\n  review       Json? // Segunda opinión del experto (cola de etiquetado): versión PUBLICADA\n  // Revisión humana en dos pasos: el BORRADOR es privado del revisor (el vocero sigue viendo el\n  // informe original) y al publicar se avisa al vocero con una notificación.\n  reviewDraft  Json? // cambios pendientes de publicar (nunca visibles para el vocero)\n  reviewSeenAt DateTime? // última vez que el vocero abrió la revisión publicada (notificación leída)\n\n  // Idioma con el que se inició la sesión ('es' | 'en'). Congela el idioma de la entrevista y de\n  // su informe: cambiar después la preferencia del vocero no altera las sesiones ya iniciadas.\n  // null en las sesiones históricas (se resuelve con el idioma del vocero o de su organización).\n  language String?\n\n  // Auditoría técnica de la transcripción por respuesta (una fila por turno).\n  transcriptionAudits TranscriptionAudit[]\n\n  // Reintentos automáticos de evaluación (aditivo: 0/null/false en sesiones históricas).\n  // Permiten recuperar el trabajo tras un reinicio y evitar que el vocero tenga que actuar.\n  evalAttempts   Int       @default(0) // ejecuciones de evaluación consumidas (persistente)\n  evalNextAt     DateTime? // próximo intento programado (null = ninguno)\n  evalLeaseUntil DateTime? // exclusión entre procesos/instancias mientras hay un intento vivo\n  evalLastError  String? // código interno del último fallo (nunca contenido del vocero)\n  evalFinishedAt DateTime? // fin del último intento\n  evalExhausted  Boolean   @default(false) // 50 intentos agotados: requiere intervención técnica\n\n  @@index([evalNextAt])\n}\n\n// Auditoría de transcripción ASR por respuesta. No sustituye al transcript: guarda qué\n// motor produjo el texto, qué intentos hubo y por qué se eligió (o por qué falló todo).\nmodel TranscriptionAudit {\n  id        String  @id @default(uuid())\n  sessionId String\n  session   Session @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  // Índice del turno dentro de Session.transcript (los identificadores reales de la sesión).\n  turnIndex Int\n\n  status     String // ok | failed\n  engine     String? // motor seleccionado (nvidia-whisper-large-v3 | nvidia-canary-1b | local-whisper-small)\n  transcript String? // texto del motor elegido (se borra con la retención y con la anonimización)\n  totalMs    Int?\n  reason     String? // motivo de la selección o del fallo (código, no texto libre del proveedor)\n  attempts   Json? // [{ engine, status, ms, code, chars }] — sin duplicar transcripciones\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([sessionId, turnIndex]) // idempotencia: una auditoría final por sesión y turno\n  @@index([sessionId])\n}\n\n// 6. Patrón maestro de evaluación\nmodel MasterPattern {\n  id      String @id @default(uuid())\n  version Int    @default(1)\n  status  String @default(\"ACTIVE\")\n\n  expressionWeight Int\n  voiceToneWeight  Int\n  coherenceWeight  Int\n  empathyWeight    Int\n\n  empathyLevel       String\n  empathyDescription String @db.Text\n\n  // Configuración detallada: criterios y rangos por área, descriptores para la IA\n  name   String?\n  config Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  createdById String\n  createdBy   User   @relation(fields: [createdById], references: [id])\n\n  scenarioRubrics ScenarioRubric[]\n  overrides       PatternOverride[]\n  voceroOverrides VoceroPatternOverride[]\n}\n\n// 8. Patrón excepcional para un escenario concreto (de una organización)\nmodel PatternOverride {\n  id        String   @id @default(uuid())\n  createdAt DateTime @default(now())\n\n  patternId String\n  pattern   MasterPattern @relation(fields: [patternId], references: [id], onDelete: Cascade)\n\n  themeId String @unique\n  theme   Theme  @relation(fields: [themeId], references: [id], onDelete: Cascade)\n}\n\n// 7. Rubrica de escenario\nmodel ScenarioRubric {\n  id String @id @default(uuid())\n\n  expressionWeight Int\n  voiceToneWeight  Int\n  coherenceWeight  Int\n  empathyWeight    Int\n\n  empathyLevel       String\n  empathyDescription String @db.Text\n\n  manuallyModified Boolean @default(false)\n\n  masterPatternId      String?\n  masterPatternVersion Int?\n\n  version Int @default(1)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  assignmentId  String             @unique\n  assignment    ScenarioAssignment @relation(fields: [assignmentId], references: [id])\n  masterPattern MasterPattern?     @relation(fields: [masterPatternId], references: [id])\n}\n\n// 9. Patrón excepcional para un vocero concreto (p. ej. dificultades del habla:\n//    más peso a lo visual). Tiene prioridad sobre el patrón del escenario.\nmodel VoceroPatternOverride {\n  id        String   @id @default(uuid())\n  createdAt DateTime @default(now())\n\n  patternId String\n  pattern   MasterPattern @relation(fields: [patternId], references: [id], onDelete: Cascade)\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// 10. Solicitud de borrado de datos de una organización (retención / derecho al olvido).\n// Flujo de estados: PENDING → APPROVED | REJECTED → COMPLETED (al completar se ejecuta el borrado).\nmodel DeletionRequest {\n  id String @id @default(uuid())\n\n  // Qué se solicita borrar: RECORDINGS = grabaciones (videos) de un vocero\n  scope  String  @default(\"RECORDINGS\")\n  reason String?\n\n  // PENDING | APPROVED | REJECTED | COMPLETED\n  status String @default(\"PENDING\")\n\n  createdAt  DateTime  @default(now())\n  resolvedAt DateTime?\n\n  resolutionNote String?\n\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  requestedById String\n  requestedBy   User   @relation(\"DeletionRequestedBy\", fields: [requestedById], references: [id])\n\n  // Vocero cuyos datos se solicitan borrar (opcional)\n  targetUserId String?\n  targetUser   User?   @relation(\"DeletionRequestTarget\", fields: [targetUserId], references: [id])\n\n  resolvedById String?\n  resolvedBy   User?   @relation(\"DeletionRequestResolvedBy\", fields: [resolvedById], references: [id])\n}\n\n// 10.b Solicitud de EXTENSIÓN del plazo de conservación.\n//\n// Es una operación DISTINTA a las solicitudes de privacidad (que borran o anonimizan): aquí el\n// admin del cliente pide conservar durante más tiempo los datos que ya existen y el\n// administrador del sistema la aprueba o rechaza. Al aprobarla se aplica de INMEDIATO\n// (retentionDays pasa al plazo solicitado), sin esperar una fecha efectiva, para que el proceso\n// automático de retención no borre los datos que la extensión protege.\nmodel RetentionExtensionRequest {\n  id String @id @default(uuid())\n\n  // PENDING | APPROVED | REJECTED  (aprobada = aplicada; no hay paso intermedio)\n  status String @default(\"PENDING\")\n\n  reason        String?\n  currentDays   Int // plazo vigente en el momento de solicitarla\n  requestedDays Int // plazo solicitado (debe ser mayor que el vigente)\n  appliedDays   Int? // plazo realmente aplicado al aprobar (trazabilidad)\n\n  createdAt      DateTime  @default(now())\n  resolvedAt     DateTime?\n  resolutionNote String?\n\n  tenantId String\n  tenant   Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  requestedById String\n  requestedBy   User   @relation(\"RetentionExtensionRequestedBy\", fields: [requestedById], references: [id])\n\n  resolvedById String?\n  resolvedBy   User?   @relation(\"RetentionExtensionResolvedBy\", fields: [resolvedById], references: [id])\n\n  @@index([tenantId, status])\n}\n\n// 11. Intervalo de pausa de la retención de un usuario (por suspensión del vocero\n// y/o de su tenant). La unión de intervalos de un usuario no se solapa: se abre un\n// intervalo cuando el usuario queda efectivamente suspendido y se cierra cuando deja\n// de estarlo (vocero y tenant activos). Permite reconstruir el tiempo de retención real.\nmodel RetentionPause {\n  id        String    @id @default(uuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  startedAt DateTime  @default(now())\n  endedAt   DateTime?\n\n  @@index([userId, endedAt])\n}\n\n// 12. Historial de cambios de estado de las organizaciones (métricas de clientes\n// ganados y perdidos). No tiene relación con Tenant ni guarda su nombre: el registro\n// sobrevive a la eliminación de la organización sin conservar datos del cliente.\nmodel TenantEvent {\n  id       String   @id @default(uuid())\n  tenantId String\n  type     String // SUSPENDED | REACTIVATED | DELETED\n  at       DateTime @default(now())\n\n  // Fecha de creación de la organización (para saber si se ganó y perdió en el mismo período)\n  tenantCreatedAt DateTime?\n\n  @@index([type, at])\n}\n\n// 13. Microlecciones: formación de voceros administrada por el equipo VoxReady.\n//\n//  - `language` es el idioma PROPIO de la lección ('es' | 'en'). No se infiere del título ni del\n//    contenido y no se traduce automáticamente: una lección en inglés solo aparece en el catálogo\n//    inglés. Si se quiere la misma temática en dos idiomas se crean dos lecciones independientes.\n//  - `areas` son las áreas de la RÚBRICA que refuerza (subconjunto de expression | voice |\n//    coherence | empathy). No se crean áreas nuevas.\n//  - `active` permite retirarla del catálogo sin borrarla.\n//  - El video vive en disco (`uploads/lessons`) y se entrega SIEMPRE por una ruta protegida.\nmodel MicroLesson {\n  id          String   @id @default(uuid())\n  title       String\n  description String\n  language    String   @default(\"es\")\n  areas       Json\n  active      Boolean  @default(true)\n  videoFile   String?\n  videoMime   String?\n  videoBytes  Int?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  createdById String?\n\n  @@index([language, active])\n}\n"
}

